@@ -0,0 +1,14 @@
+import { project } from "./project.ts";
+import { allRecords, recordsForPath } from "./query.ts";
+
+export const contextForPath = (repo: string, filePath: string): string | null => {
+  const records = recordsForPath(repo, filePath);
+  if (records.length === 0) return null;
+  return project(records);
+};
+
+export const sessionContext = (repo: string): string | null => {
+  const records = allRecords(repo);
+  if (records.length === 0) return null;
+  return project(records);
+};
