+export interface Record {
+  readonly id: string;
+  readonly type: "limit" | "ruled-out" | "warn";
+  readonly title: string;
+  readonly content: string;
+  readonly certainty: "firm" | "tentative" | "exploratory";
+}
+
+export const project = (records: readonly Record[]): string => {
+  if (records.length === 0) return "";
+
+  const sections = groupByType(records);
+  const output: string[] = [];
+
+  output.push("## CommitLore — decisions relevant to this file\n");
+
+  if (sections.limit.length > 0) {
+    output.push("### Active limits");
+    sections.limit.forEach((r) => {
+      output.push(`- ${r.title}: ${r.content}`);
+    });
+    output.push("");
+  }
+
+  if (sections["ruled-out"].length > 0) {
+    output.push("### Ruled out — do not re-propose without new evidence");
+    sections["ruled-out"].forEach((r) => {
+      output.push(`- ${r.title} — ${r.content}`);
+    });
+    output.push("");
+  }
+
+  if (sections.warn.length > 0) {
+    output.push("### Warnings");
+    sections.warn.forEach((r) => {
+      output.push(`- ${r.title}: ${r.content}`);
+    });
+    output.push("");
+  }
+
+  return output.join("\n");
+};
+
+const groupByType = (
+  records: readonly Record[],
+): Record<Record["type"], Record[]> => ({
+  limit: records.filter((r) => r.type === "limit"),
+  "ruled-out": records.filter((r) => r.type === "ruled-out"),
+  warn: records.filter((r) => r.type === "warn"),
+});
